235→export default function App() {
236→  const [tables, setTables] = useState<TableInfo[]>([]);
237→  const [loading, setLoading] = useState(true);
238→  const [error, setError] = useState<string | null>(null);
239→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
240→
241→  const refreshTables = useCallback(async () => {
242→    try {
243→      const response = await fetch('/api/tables');
244→      if (!response.ok) throw new Error('Failed to fetch tables');
245→      const data = await response.json();
246→      setTables(data);
247→    } catch (e) {
248→      console.error('Failed to refresh tables:', e);
249→    }
250→  }, []);
251→
252→  useEffect(() => {
253→    (async () => {
254→      try {
255→        const response = await fetch('/api/health');
256→        if (!response.ok) throw new Error('Backend is not available');
257→        await refreshTables();
258→        try {
259→          const lfRes = await fetch('/api/langfuse/status');
260→          if (lfRes.ok) {
261→            setLangfuseStatus(await lfRes.json());
262→          }
263→        } catch {
264→          // Langfuse status fetch is non-critical
265→        }
266→      } catch (e) {
267→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
268→      } finally {
269→        setLoading(false);
270→      }
271→    })();
272→  }, [refreshTables]);
273→
274→  if (loading) {
275→    return <div className="app-loading">Connecting to backend...</div>;
276→  }
277→
278→  if (error) {
279→    return (
280→      <div className="app-error">Failed to connect: {error}</div>
281→    );
282→  }
283→
284→  return (
285→    <LanguageProvider>
286→      <ThemeProvider>
287→        <AgentProvider refreshTables={refreshTables}>
288→          <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
289→        </AgentProvider>
290→      </ThemeProvider>
291→    </LanguageProvider>
292→  );
293→}
